L000471	\section{Gravitons on $S^{d+1}$}
L000472	
L000473	The one-loop path integral for gravitons on the round $S^{d+1}$, of radius
L000474	$\ell_\text{dS} \equiv \sqrt{\tfrac{d(d-1)}{2\Lambda}}$, can be written in terms of functional determinants \cite{Gibbons:1978ji, Christensen:1979iy, Fradkin:1983mq, Allen:1983dg, Taylor:1989ua, GRIFFIN1989295, Mazur:1989ch, Vassilevich:1992rk, Volkov:2000ih, Polchinski:1988ua, Anninos:2020hfj, Law:2020cpj}:
L000475	\begin{align}
L000476	      Z^\text{1-loop}_\text{PI}\!\left[S^{d+1} \right]
L000477	      =  \frac{i^{\,d+3}}{\text{Vol}\left(G\right)_{\text{PI}}}\,
L000478	      \frac{\det\nolimits_{-1}'\!\left|-\nabla_{1,S}^2-\tfrac{d}{\ell_\text{dS}^2}\right|^{1/2}}
L000479	           {\det_{-1}\!\left|-\nabla_{2,S}^2+\tfrac{2}{\ell_\text{dS}^2}\right|^{1/2}} \;.
L000480	\end{align}
L000481	Here $-\nabla_{1,S}^2$ and $-\nabla_{2,S}^2$ denote the transverse vector Laplacian and the symmetric transverse–traceless (STT) spin-2 Laplacian on $S^{d+1}$. A prime indicates omission of zero modes of the corresponding Laplace-type operator, and the subscript “$-1$’’ denotes that the product over spherical harmonics is extended to start at the $SO(d{+}2)$ label $L=-1$. The isometry group is $G=SO(d+2)$, whose volume is
L000482	\begin{align}\label{eq:ZPIvolgrav}
L000483		\text{Vol}(G)_{\rm PI} = \text{Vol}(G)_c \left( \frac{\text{Vol}(S^{d-1})\,\ell_\text{dS}^{\,d-1}}{8\pi G_N\, d(d+2)}\right)^{\tfrac{\dim SO(d+2)}{2}} \;,
L000484	\end{align}
L000485	measured in the $G_N$-dependent metric induced by the path-integral measure. The ``canonical" volume of $SO(d+2)$ is defined using the invariant group metric normalized so that the minimal $SO(2)$ orbits have length $2\pi$:
L000486	\begin{align}\label{eq:volumes}
L000487		\text{Vol}(G)_c = \prod_{k=2}^{d+2} \text{Vol}\left(S^{k-1}\right)\;,
L000488		\;
L000489		\text{Vol}\left(S^n\right) = \frac{2\pi^{\tfrac{n+1}{2}}}{\Gamma\!\left(\tfrac{n+1}{2}\right)} \;.
L000490	\end{align}
L000491	
L000492	After some manipulations \cite{Anninos:2020hfj}, one finds the factorization \eqref{introeq:PIsplit}.
L000493	In the bulk sector \eqref{introeq:Zbulk}, the Harish–Chandra character for a graviton takes the form
L000494	\begin{align}
L000495		&\quad \chi(t)	\nn\\
L000496	    &=  \sum_{I=0}^2 \sum_{n=0}^\infty \sum_{l=2}^\infty
L000497	    D^d_{l,I} \left(e^{-\frac{I+2n+l}{\ell_\text{dS}}|t|} + e^{-\frac{d-I+2n+l}{\ell_\text{dS}}|t|}\right)\nn\\
L000498	    &=  \left[ \frac{(d+2)(d-1)}{2}\, \frac{q^d+1}{|1-q|^d}
L000499	       - d\,\frac{q^{d+1}+q^{-1}}{|1-q|^d}\right]_+ \;,
L000500	\end{align}
L000501	where $q\equiv e^{-t/\ell_\text{dS}}$.
L000502	On the first line, the exponents encode the physical QNM frequencies for a graviton in the $dS_{d+1}$ static patch \cite{Lopez-Ortega:2006aal}.
L000503	Here $I=0,1,2$ label scalar, vector, and tensor modes, respectively; $n$ is the overtone number; and $l$ is the total $SO(d)$ angular momentum.
L000504	The degeneracy $D^d_{l,I}$ is the dimension of a two-row representation of $SO(d)$ \cite{rubin1984eigenvalues,Higuchi:1986wu}.
L000505	The notation $[\,\cdots\,]_+$ in the second line denotes the following ``flipping'' operation on a small-$q$ expansion
L000506	\begin{align}\label{eq:flipnotation}
L000507		\left[\sum_k c_k q^k \right]_+
L000508	    \equiv \sum_k c_k q^k - c_0 - \sum_{k<0} c_k \left(q^k + q^{-k}\right) \;.
L000509	\end{align}
L000510	
L000511	For completeness, the full expression for the edge contribution \eqref{eq:Zedgeold} is
L000512	\begin{align}
L000513	     Z_{\rm edge}
L000514	    & =\frac{i^{d+3} }{ \text{Vol}(G)_c }
L000515	         \left(\frac{32\pi^3 G_N}{\text{Vol}(S^{d-1})\ell_\text{dS}^{d-1}}\right)^{\frac{\dim SO(d+2)}{2}} \nn\\
L000516	    &\quad \times \exp\bigg\{-\int_0^\infty \frac{dt}{2t}\frac{1+q}{1-q}\nn\\
L000517	   & \qquad  \times \left[(d+2)\frac{q^{d-1}+q^{-1}}{(1-q)^{d-2}}-\frac{q^{d}+q^{-2}}{(1-q)^{d-2}} \right]_+ \bigg\}\;.
L000518	\end{align}
