L000521	\section{Gravitons on $S^2\times S^{d-1}$}
L000522	
L000523	The one-loop path integral for gravitons on $S^2\times S^{d-1}$ ($d\geq 3$), with radii
L000524	$\ell_N \equiv \sqrt{\tfrac{d-1}{2\Lambda}}$ and $r_N \equiv \sqrt{d-2}\,\ell_N$, can be written in terms of functional determinants \cite{Volkov:2000ih,Law:2025yec}:
L000525	\begin{align}
L000526	     & \quad Z^\text{1-loop}_\text{PI}\!\left[S^2 \times S^{d-1} \right] \nn\\
L000527	 &    =  \frac{1}{\text{Vol}\!\left(G\right)_{\text{PI}}}\,
L000528	       \left( \frac{d-1}{4\Lambda}\right)^{\frac12}
L000529	       \frac{\det\nolimits'\!\left( -\nabla_{1,N}^2-\tfrac{d-2}{r_N^2}\right)^{\frac12}}
L000530	            {\det\!\left| D^2\right|^{\frac12}} \;.
L000531	\end{align}
L000532	Here $-\nabla_{1,N}^2$ is the transverse vector Laplacian on $S^2\times S^{d-1}$, while
L000533	\begin{align}\label{eq:TTLaplacian}
L000534	    D^2_{\mu\nu\alpha\beta}  \equiv - g_{\mu\alpha}g_{\nu\beta}\nabla^2  - 2 R_{\mu \alpha \nu \beta}
L000535	\end{align}
L000536	is the kinetic operator acting on the transverse–traceless (TT) part of the graviton.
L000537	The isometry group is $G=SO(3)\times SO(d)$, whose path-integral volume is related to the canonical volume,
L000538	\begin{align}
L000539	    \text{Vol}(G)_c = 8\pi^2 \prod_{I=1}^{d-1} \text{Vol}\!\left(S^I\right) \;,
L000540	\end{align}
L000541	through
L000542	\begin{align}\label{eq:NariaiGPI}
L000543		& \quad \text{Vol}\!\left(G\right)_{\text{PI}} \nn\\
L000544		& = \left( \frac{A}{8\pi G_N}\,\frac{\ell_N^4}{3} \right)^{\frac32}
L000545		  \left( \frac{A}{8\pi G_N}\,\frac{r_N^2\ell_N^2}{d}   \right)^{\tfrac{d(d-1)}{4}}
L000546		  \text{Vol}\!\left(G\right)_{c} \,,
L000547	\end{align}
L000548	where $A=2\times r_N^{\,d-1}\,\text{Vol}\!\left(S^{d-1}\right)$ is the total area of the black-hole and cosmological horizons of the Nariai spacetime.
L000549	
L000550	One finds the factorization \eqref{eq:ZPINariai}. The bulk part takes the same form as \eqref{introeq:Zbulk}, but with
L000551	\begin{align}
L000552	    \chi(t) &\equiv \sum_{I=0}^2\sum_{l=2}^\infty \sum_{n=0}^\infty D^d_{l,I} \, \left( e^{-i \omega^I_{nl}|t| } +e^{-i {\tilde\omega}^I_{nl}|t| }\right)\nn\\
L000553	    &= \sum_{I=0}^2\sum_{l=2}^\infty D^d_{l,I} \, \frac{e^{-\Delta_{I,l}\frac{|t|}{\ell_N}}+e^{-\bar\Delta_{I,l}\frac{|t|}{\ell_N}}}{1-e^{-\frac{|t|}{\ell_N}}} \;.
L000554	\end{align}
L000555	On the first line, the exponents encode the graviton QNM spectrum in the Lorentzian Nariai geometry \cite{Vanzo:2004fy,Lopez-Ortega:2007llk,Lopez-Ortega:2009flo,Venancio:2020ttw}:
L000556	\begin{gather}
L000557	    i \omega^I_{nl} = \frac{\Delta_{I,l}+n}{\ell_N} \qquad \text{and} \qquad i {\tilde\omega}^I_{nl} =\frac{\bar\Delta_{I,l}+n}{\ell_N}, \nn\\
L000558	    \text{where}\;\; \Delta_{I,l} =1-\bar\Delta_{I,l}= \frac12 + i \nu_{I,l} \;\; \text{with} \nn\\
L000559	      \nu_{I,l}\equiv  \sqrt{\frac{l\,(l+d-2)-(2-I)(d-2+I)}{d-2} -\frac{1}{4} } \;,
L000560	\end{gather}
L000561	with $I=0,1,2$ labeling scalar, vector, and tensor modes, $n$ the overtone number, $l$ the total $SO(d)$ angular momentum, and $D^d_{l,I}$ the degeneracies.
L000562	
L000563	On the other hand, the edge partition function is
L000564	\begin{align}\label{eq:Zedgedet}
L000565	    &\quad Z_{\rm edge} \nn\\
L000566	    &= \frac{1}{\text{Vol}\!\left(G\right)_{\text{PI}}}
L000567	       \left[ \det\nolimits_{-1}' \!\left| -\nabla_1^2-\tfrac{d-2}{r^2_N}\right|^{\frac12}
L000568	              \det\nolimits' \!\left(-\nabla_0^2\right)^{\frac32} \right]^2 .
L000569	\end{align}
